    private static Brush Brush(string hex) =>
        new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)!);

    private static Color Color(string hex) =>
        (Color)ColorConverter.ConvertFromString(hex)!;

    private static void Add(DrawingGroup g, string path, Brush brush) =>
        g.Children.Add(new GeometryDrawing(brush, null, Geometry.Parse(path)));

    private static void Add(DrawingGroup g, Geometry geometry, Brush brush) =>
        g.Children.Add(new GeometryDrawing(brush, null, geometry));

    private static void Add(DrawingGroup g, Geometry geometry, Pen pen) =>
        g.Children.Add(new GeometryDrawing(null, pen, geometry));

    private static Geometry Polygon(string points)
    {
        StreamGeometry geometry = new();
        using StreamGeometryContext ctx = geometry.Open();
        string[] items = points.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        for (int i = 0; i < items.Length; i += 2)
        {
            Point point = new(
                double.Parse(items[i], CultureInfo.InvariantCulture),
                double.Parse(items[i + 1], CultureInfo.InvariantCulture));
            if (i == 0) ctx.BeginFigure(point, true, true);
            else ctx.LineTo(point, true, false);
        }

        geometry.Freeze();
        return geometry;
    }

    private static Geometry Rect(double x, double y, double width, double height, double rx = 0, Transform? transform = null)
    {
        RectangleGeometry geometry = new(new Rect(x, y, width, height), rx, rx, transform);
        geometry.Freeze();
        return geometry;
    }

